"""Aperçu hors ligne du nouveau kit, avec vrai contrôle des calques."""
from pathlib import Path
import base64
import hashlib
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "tilesheets"
manifest = json.loads((OUT / "kit.json").read_text())
assets = {}
index = {}


def embed(path):
    raw = (OUT / path).read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest not in index:
        key = f"i{len(index)}"
        index[digest] = key
        assets[key] = "data:image/png;base64," + base64.b64encode(raw).decode()
    return index[digest]


data = {"objects": [], "modules": [], "sheets": {}, "spirals": {}, "assets": assets}
for mode in ["jour", "nuit"]:
    data["sheets"][mode] = {key: embed(path) for key, path in {
        "objets": f"objets/objets_{mode}.png", "ombres_objets": f"objets/ombres_{mode}.png",
        "parquet": f"parquet/parquet_{mode}.png", "spirales": f"spirales/spirales_{mode}.png",
        "structure": f"architecture/structure_{mode}.png", "contacts": f"architecture/contacts_{mode}.png"}.items()}
    data["spirals"][mode] = [embed(f"spirales/individuelles/spirale_{i:02d}_{mode}.png") for i in range(1, 17)]
for obj in manifest["objets"]:
    q = {k: obj[k] for k in ["id", "nom", "groupe", "taille", "pivot"]}
    q["images"] = {mode: {kind: embed(path) for kind, path in files.items()} for mode, files in obj["fichiers"].items()}
    data["objects"].append(q)
for item in manifest["modules"]:
    q = {k: item[k] for k in ["id", "nom", "dimensions", "acces", "famille"]}
    q["images"] = {mode: {"png": embed(files["png"]), "layers": [embed(p) for p in files["calques"]]} for mode, files in item["fichiers"].items()}
    q["downloads"] = {mode: {k: v for k, v in f.items() if k in ["aseprite", "tiled"]} for mode, f in item["fichiers"].items()}
    data["modules"].append(q)

